import heapq

def cheapest(graph, src, dst, k):
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == dst:
            return d
        if d > dist.get(u, float('inf')):
            continue
        for v, c in graph.get(u, []):
            if d + c < dist.get(v, float('inf')):
                dist[v] = d + c
                heapq.heappush(pq, (d + c, v))
    return None

