import time

class TransientError(Exception):
    pass

def retry(fn, attempts=3, base_delay=0.1, sleep=time.sleep):
    """Call fn(); on TransientError wait base_delay, 2*base_delay, 4*base_delay ... between attempts and try
    again, up to `attempts` calls in total. Any other exception propagates at once. After the last failed
    attempt the last TransientError propagates."""
    delay = base_delay
    for i in range(attempts):
        try:
            return fn()
        except Exception:
            sleep(delay)
            delay += base_delay
    return None

